cat > client/src/api.js << 'EOF'
import axios from 'axios';

const API = axios.create({
  baseURL: 'http://localhost:5000/api'
});

API.interceptors.request.use((config) => {
  const token = localStorage.getItem('token');
  if (token) {
    config.headers.Authorization = `Bearer ${token}`;
  }
  return config;
});

export const register = (username, password) =>
  API.post('/auth/register', { username, password });

export const login = (username, password) =>
  API.post('/auth/login', { username, password });

export const getExpenses = () =>
  API.get('/expenses');

export const createExpense = (type, category, amount, description, date) =>
  API.post('/expenses', { type, category, amount, description, date });

export const deleteExpense = (id) =>
  API.delete(`/expenses/${id}`);
EOF

cat > <RUN_DIR>/memo.js << 'EOF'
#!/usr/bin/env node
import readline from 'node:readline';
import fs from 'node:fs';
import path from 'node:path';

const dbPath = path.join(process.env.HOME || '.', '.memo-data.json');

function loadMemos() {
  try {
    if (fs.existsSync(dbPath)) {
      const data = fs.readFileSync(dbPath, 'utf-8');
      return JSON.parse(data);
    }
  } catch (e) {
    console.error('메모 로드 실패:', e.message);
  }
  return [];
}

function saveMemos(memos) {
  try {
    fs.writeFileSync(dbPath, JSON.stringify(memos, null, 2));
  } catch (e) {
    console.error('메모 저장 실패:', e.message);
  }
}

const memos = loadMemos();
const rl = readline.createInterface({ input: process.stdin, output: process.stdout });

console.log('메모를 입력하세요. "목록" 은 전체 보기, "끝" 은 종료.');
rl.on('line', (line) => {
  const text = line.trim();
  if (text === '끝') {
    saveMemos(memos);
    return rl.close();
  }
  if (text === '목록') {
    if (memos.length === 0) {
      console.log('저장된 메모가 없습니다.');
    } else {
      memos.forEach((memo, i) => console.log(`${i + 1}. ${memo}`));
    }
    return;
  }
  if (text !== '') {
    memos.push(text);
    saveMemos(memos);
    console.log('저장되었습니다.');
  }
});
EOF

