const { app, BrowserWindow } = require('electron');
const path = require('path');

function createWindow() {
  const mainWindow = new BrowserWindow({
    width: 900,
    height: 700,
    webPreferences: {
      preload: path.join(__dirname, 'preload.js'),
      nodeIntegration: false,
      contextIsolation: true,
    },
  });

  mainWindow.loadFile('index.html');
}

app.on('ready', createWindow);

app.on('window-all-closed', () => {
  if (process.platform !== 'darwin') {
    app.quit();
  }
});

app.on('activate', () => {
  const allWindows = BrowserWindow.getAllWindows();
  if (allWindows.length === 0) {
    createWindow();
  }
});
EOF

cat > <RUN_DIR>/memo.js << 'EOF'
#!/usr/bin/env node
// 메모 프로그램. JSON 파일에 메모를 저장한다.
import readline from 'node:readline';
import fs from 'node:fs';
import path from 'node:path';

const memoFile = path.join(process.env.HOME, '.memos.json');

const loadMemos = () => {
  try {
    if (fs.existsSync(memoFile)) {
      const data = fs.readFileSync(memoFile, 'utf-8');
      return JSON.parse(data);
    }
  } catch (e) {}
  return [];
};

const saveMemos = (memos) => {
  fs.writeFileSync(memoFile, JSON.stringify(memos, null, 2));
};

const memos = loadMemos();
const rl = readline.createInterface({ input: process.stdin, output: process.stdout });

console.log('메모를 입력하세요. "목록" 은 전체 보기, "끝" 은 종료.');
rl.on('line', (line) => {
  const text = line.trim();
  if (text === '끝') {
    saveMemos(memos);
    return rl.close();
  }
  if (text === '목록') {
    memos.forEach((memo, i) => console.log(`${i + 1}. ${memo}`));
    return;
  }
  if (text !== '') {
    memos.push(text);
    saveMemos(memos);
  }
});
EOF
